// aim.cpp
// World-to-screen projection + smoothed crosshair delta for VALORANT.
// Build (standalone smoke test):
//   cl /std:c++17 /O2 /W4 /DSTANDALONE aim.cpp /link user32.lib gdi32.lib
//
// Exported helpers (all in AimHelper namespace):
//   WorldToScreen   – projects a 3-D world position to 2-D screen coords
//   GetHeadDelta    – returns a smoothed (x,y) pixel delta toward an entity's head
//   SmoothDelta     – applies speed-weighted smoothing to a raw delta

#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#include <cmath>
#include <algorithm>
#include <optional>

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

struct Vec2 { float x, y; };
struct Vec3 { float x, y, z; };

// Column-major 4x4 view-projection matrix (matches DirectX convention).
struct Matrix4x4 {
    float m[4][4];
};

struct EntitySnapshot {
    Vec3  headPos;      // world-space head bone position
    bool  alive;
};

// ---------------------------------------------------------------------------
// AimHelper
// ---------------------------------------------------------------------------

namespace AimHelper {

// --- WorldToScreen ---------------------------------------------------------
//
// Projects `worldPos` through `vp` (view-projection matrix) into viewport
// coordinates [0, screenW] x [0, screenH].
//
// Returns std::nullopt when the point is behind the camera (w <= 0).

std::optional<Vec2> WorldToScreen(
    const Vec3&      worldPos,
    const Matrix4x4& vp,
    int              screenW,
    int              screenH)
{
    // Multiply worldPos by the view-projection matrix.
    float clipX = worldPos.x * vp.m[0][0] + worldPos.y * vp.m[1][0]
                + worldPos.z * vp.m[2][0] + vp.m[3][0];
    float clipY = worldPos.x * vp.m[0][1] + worldPos.y * vp.m[1][1]
                + worldPos.z * vp.m[2][1] + vp.m[3][1];
    float clipW = worldPos.x * vp.m[0][3] + worldPos.y * vp.m[1][3]
                + worldPos.z * vp.m[2][3] + vp.m[3][3];

    if (clipW <= 0.001f)
        return std::nullopt;          // behind camera – skip

    // Perspective divide -> NDC in [-1, 1].
    float ndcX = clipX / clipW;
    float ndcY = clipY / clipW;

    // NDC -> screen pixels.
    float sx = ( ndcX + 1.0f) * 0.5f * static_cast<float>(screenW);
    float sy = (-ndcY + 1.0f) * 0.5f * static_cast<float>(screenH);

    return Vec2{ sx, sy };
}

// --- SmoothDelta -----------------------------------------------------------
//
// Blends `raw` toward zero with a strength in [0.0, 1.0].
// strength == 0  -> delta unchanged (instant snap)
// strength == 1  -> delta zeroed    (no movement)
//
// A typical value is 0.05 – 0.20 for natural-feeling smoothing.

Vec2 SmoothDelta(Vec2 raw, float strength)
{
    strength = std::clamp(strength, 0.0f, 1.0f);
    return Vec2{ raw.x * (1.0f - strength),
                 raw.y * (1.0f - strength) };
}

// --- GetHeadDelta ----------------------------------------------------------
//
// Projects `entity.headPos` to screen and returns the signed pixel delta from
// the current crosshair centre (screenW/2, screenH/2).
//
// The result is restricted to a circular cone of `coneRadius` pixels.
// If the head projection falls outside the cone, or the entity is dead,
// returns std::nullopt so the caller can skip to the next candidate.
//
// `smoothStrength` is forwarded to SmoothDelta before returning.

std::optional<Vec2> GetHeadDelta(
    const EntitySnapshot& entity,
    const Matrix4x4&      vp,
    int                   screenW,
    int                   screenH,
    float                 coneRadius,     // pixels, default: 240
    float                 smoothStrength) // [0,1],  default: 0.08
{
    if (!entity.alive)
        return std::nullopt;

    auto projected = WorldToScreen(entity.headPos, vp, screenW, screenH);
    if (!projected)
        return std::nullopt;

    float cx = static_cast<float>(screenW) * 0.5f;
    float cy = static_cast<float>(screenH) * 0.5f;

    float dx = projected->x - cx;
    float dy = projected->y - cy;

    // Reject if outside the cone.
    float distSq = dx * dx + dy * dy;
    if (distSq > coneRadius * coneRadius)
        return std::nullopt;

    Vec2 raw{ dx, dy };
    return SmoothDelta(raw, smoothStrength);
}

} // namespace AimHelper

// ---------------------------------------------------------------------------
// Smoke test – compiled only when STANDALONE is defined
// ---------------------------------------------------------------------------

#ifdef STANDALONE

#include <cstdio>

int main()
{
    // Minimal identity VP matrix: orthographic, maps world 1:1 to screen.
    // Columns 0..3 correspond to x, y, z, w contributions.
    Matrix4x4 vp{};
    vp.m[0][0] = 1.0f;  // x  -> clipX
    vp.m[1][1] = 1.0f;  // y  -> clipY
    vp.m[3][3] = 1.0f;  // homogeneous w = 1

    const int W = 1920, H = 1080;

    // --- WorldToScreen ---
    Vec3 head{ static_cast<float>(W) * 0.5f + 50.0f,   // 50 px right of centre
               static_cast<float>(H) * 0.5f - 30.0f,   // 30 px above centre (Y up)
               0.0f };

    auto screen = AimHelper::WorldToScreen(head, vp, W, H);
    if (screen)
        printf("WorldToScreen: (%.1f, %.1f)\n", screen->x, screen->y);
    else
        printf("WorldToScreen: behind camera\n");

    // --- GetHeadDelta inside 240 px cone ---
    AimHelper::EntitySnapshot ent{ head, true };
    auto delta = AimHelper::GetHeadDelta(ent, vp, W, H, 240.0f, 0.08f);
    if (delta)
        printf("HeadDelta (smoothed 8%%): dx=%.2f  dy=%.2f\n",
               delta->x, delta->y);
    else
        printf("HeadDelta: outside cone or dead\n");

    // --- GetHeadDelta outside cone ---
    Vec3 farHead{ static_cast<float>(W) * 0.5f + 400.0f,
                  static_cast<float>(H) * 0.5f,
                  0.0f };
    AimHelper::EntitySnapshot farEnt{ farHead, true };
    auto farDelta = AimHelper::GetHeadDelta(farEnt, vp, W, H, 240.0f, 0.08f);
    printf("FarDelta (should be nullopt): %s\n",
           farDelta ? "HAS VALUE (unexpected)" : "nullopt (correct)");

    // --- SmoothDelta edge cases ---
    Vec2 raw{ 100.0f, 80.0f };
    Vec2 s0  = AimHelper::SmoothDelta(raw, 0.0f);
    Vec2 s1  = AimHelper::SmoothDelta(raw, 1.0f);
    Vec2 s50 = AimHelper::SmoothDelta(raw, 0.5f);
    printf("Smooth(0.0): (%.1f, %.1f)\n", s0.x,  s0.y);
    printf("Smooth(1.0): (%.1f, %.1f)\n", s1.x,  s1.y);
    printf("Smooth(0.5): (%.1f, %.1f)\n", s50.x, s50.y);

    return 0;
}

#endif // STANDALONE
